#include <algorithm>
#include <cstdint>
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;
struct Gate { int op,a,b; };
int n,p,l,limit; vector<uint64_t> values; vector<unsigned> reach; vector<Gate> gates;
vector<uint64_t> targets; vector<unsigned> edgeMasks; vector<int> lower; vector<unsigned> requiredOr; unsigned seenTarget=0;
uint64_t visits=0, checked=0; unordered_map<uint64_t,int> targetIndex; vector<int> matched;
int cover(unsigned E){int r=n;for(unsigned s=0;s<(1u<<n);s++){bool yes=true;for(int a=0;a<p;a++)for(int b=0;b<l;b++)if((E>>(a*l+b)&1)&&!(s>>a&1)&&!(s>>(p+b)&1))yes=false;if(yes)r=min(r,__builtin_popcount(s));}return r;}
uint64_t orTruth(unsigned S){uint64_t f=0;for(unsigned x=0;x<(1u<<n);x++)if(x&S)f|=1ull<<x;return f;}
bool starServed(unsigned E){for(int a=0;a<p;a++)for(int b=0;b<l;b++)if(E>>(a*l+b)&1){bool ok=false;for(int j=0;j<(int)gates.size();j++)if(gates[j].op==1){for(unsigned S=1;S<(1u<<l);S++)if(__builtin_popcount(S)>=2&&(S>>b&1)&&values[n+j]==orTruth(S<<p)){bool good=true;for(int c=0;c<l;c++)if((S>>c&1)&&!(E>>(a*l+c)&1))good=false;if(good)ok=true;}for(unsigned S=1;S<(1u<<p);S++)if(__builtin_popcount(S)>=2&&(S>>a&1)&&values[n+j]==orTruth(S)){bool good=true;for(int c=0;c<p;c++)if((S>>c&1)&&!(E>>(c*l+b)&1))good=false;if(good)ok=true;}}if(!ok)return false;}return true;}
void dfs(){visits++;int k=gates.size();bool pushed=false;if(k){auto it=targetIndex.find(values.back());if(it!=targetIndex.end()&&k<lower[it->second]){matched.push_back(it->second);pushed=true;}for(int t:matched)if(k<lower[t]){checked++;if(starServed(edgeMasks[t])){cout<<"COUNTEREXAMPLE n="<<n<<" p="<<p<<" E="<<edgeMasks[t]<<" lower="<<lower[t]<<" gates="<<k<<endl;for(auto g:gates)cout<<g.op<<" "<<g.a<<" "<<g.b<<endl;exit(2);}}}if(k<limit){int m=values.size();for(int a=0;a<m;a++)for(int b=a;b<m;b++)for(int op=0;op<2;op++){unsigned r=op?(reach[a]|reach[b]):0;unsigned left=(1u<<p)-1,right=((1u<<l)-1)<<p;if((r&left)&&(r&right))continue;uint64_t f=op?(values[a]|values[b]):(values[a]&values[b]);values.push_back(f);reach.push_back(r);gates.push_back({op,a,b});dfs();gates.pop_back();reach.pop_back();values.pop_back();}}if(pushed)matched.pop_back();}
int main(int argc,char**argv){if(argc<4){cerr<<"usage: n p max_gates [family [pruning]]"<<endl;return 64;}n=atoi(argv[1]);p=atoi(argv[2]);l=n-p;limit=atoi(argv[3]);if(n<2||n>6||p<1||p>=n||limit<0||limit>=32){cerr<<"unsupported arguments"<<endl;return 64;}for(int i=0;i<n;i++){values.push_back(orTruth(1u<<i));reach.push_back(1u<<i);}for(unsigned E=1;E<(1u<<(p*l));E++){bool c4=false,bare=false;for(int a=0;a<p;a++)for(int b=0;b<l;b++)if(E>>(a*l+b)&1){int da=0,db=0;for(int c=0;c<l;c++)da+=E>>(a*l+c)&1;for(int c=0;c<p;c++)db+=E>>(c*l+b)&1;if(da<2&&db<2)bare=true;}for(int a=0;a<p;a++)for(int aa=a+1;aa<p;aa++)for(int b=0;b<l;b++)for(int bb=b+1;bb<l;bb++)if((E>>(a*l+b)&1)&&(E>>(aa*l+b)&1)&&(E>>(a*l+bb)&1)&&(E>>(aa*l+bb)&1))c4=true;if(c4||bare)continue;int lb=__builtin_popcount(E)+cover(E)-1;if(lb<=1)continue;uint64_t f=0;for(unsigned x=0;x<(1u<<n);x++){bool y=false;for(int a=0;a<p;a++)for(int b=0;b<l;b++)if((E>>(a*l+b)&1)&&(x>>a&1)&&(x>>(p+b)&1))y=true;if(y)f|=1ull<<x;}targetIndex[f]=targets.size();targets.push_back(f);edgeMasks.push_back(E);lower.push_back(lb);}cout<<"n="<<n<<" p="<<p<<" limit="<<limit<<" target_count="<<targets.size()<<endl;dfs();cout<<"DONE visits="<<visits<<" target_hits="<<checked<<" no_counterexample"<<endl;}
